function Matches() {
  const { data } = useApp(); const params = useAppQuery();
  const offers = data.listings.filter(l => l.ownerId === data.actor!.id && l.status === 'active' && tradeEnabled(l) && !l.loanHeld);
  const [offerId, setOfferId] = useState(params.get('item') ?? offers[0]?.id ?? ''), [candidates, setCandidates] = useState<Candidate[]>([]), [reason, setReason] = useState(''), [loading, setLoading] = useState(true), [error, setError] = useState('');
  const [selected, setSelected] = useState<Candidate | null>(null), requestSequence = useRef(0);
  const activeOfferId = String(offers.some(l => l.id === offerId) ? offerId : offers[0]?.id ?? '');
  const fingerprint = data.matchingToken ?? JSON.stringify(data.listings.map(l => [l.id, l.version, l.status, l.loanHeld]));
  const clockMinute = Math.floor(data.serverTime / 60);
  const searchMatches = useCallback(async () => {
    const sequence = ++requestSequence.current;
    await Promise.resolve();
    if (sequence !== requestSequence.current) return;
    setCandidates([]); setSelected(null); setLoading(!!activeOfferId); setError('');
    if (!activeOfferId) return;
    try {
      const result = await api<{ candidates: Candidate[]; reason: string | null }>('matches', { offeredIds: [activeOfferId] });
      if (sequence === requestSequence.current) { setCandidates(result.candidates); setReason(result.reason ?? ''); }
    } catch (e) { if (sequence === requestSequence.current) setError((e as Error).message); }
    finally { if (sequence === requestSequence.current) setLoading(false); }
  }, [activeOfferId, setCandidates, setSelected, setLoading, setError, setReason]);
  const invalidateMatches = useCallback(() => { requestSequence.current++; }, []);
  useEffect(() => {
    let active = true;
    queueMicrotask(() => { if (active) void searchMatches(); });
    return () => { active = false; invalidateMatches(); };
  }, [searchMatches, invalidateMatches, fingerprint, clockMinute]);
  return <><PageHeading eyebrow="A NEW WAY AROUND" title="Find a loop that fits." description="Every exchange meets your wants and everyone's meeting preferences." />{offers.length ? <><div className="match-controls"><label>I&apos;m offering</label><Pick value={activeOfferId} onChange={id => { setOfferId(id); setAppQuery({ item: id }); setLoading(true); setError(''); }} label="Your offered item" options={offers.map(l => ({ value: l.id, label: l.title }))} /><button className="secondary" onClick={searchMatches} disabled={loading}><RefreshCw size={16} className={loading ? 'spin' : ''} />Refresh matches</button></div>{error && <div className="form-error" role="alert">{error}</div>}{loading ? <div className="loading-grid"><Skeleton className="h-72 rounded-xl" /><Skeleton className="h-72 rounded-xl" /></div> : candidates.length ? <><div className="section-heading"><h2>{candidates.length} possible {candidates.length === 1 ? 'loop' : 'loops'}</h2><span>Ranked by your stated priorities</span></div><div className="match-list">{candidates.map(c => <CandidateCard key={c.key} candidate={c} onReview={() => setSelected(c)} />)}</div></> : <EmptyState title={reason === 'no_common_time' ? 'The wants fit, but the timing needs work' : reason === 'no_common_venue' ? 'The wants fit, but there is no shared venue' : 'No compatible loop yet'} description={reason === 'no_common_time' ? 'Try adding more of your own availability. A loop needs one shared 30-minute slot.' : reason === 'no_common_venue' ? 'Review your accepted public venues. Everyone must agree to the same place.' : 'Try a different item or broaden your own wants. Items and members may also be temporarily unavailable.'}><Link className="secondary" href="/settings">Review my preferences</Link></EmptyState>}</> : <EmptyState title="Start with an available item" description="Publish an item and its structured wants before finding swaps."><Link href="/listings/new" className="primary">List an item</Link></EmptyState>}<ProposalDialog key={selected?.key ?? 'closed'} candidate={selected} close={() => setSelected(null)} /></>;
}
