function ReportDialog({ open, setOpen, id, listing = false }: { open: boolean; setOpen: (open: boolean) => void; id: string; listing?: boolean }) {
  const { action, busy } = useApp(); const [kind, setKind] = useState('condition'), [details, setDetails] = useState(''), [error, setError] = useState('');
  return <Dialog open={open} onOpenChange={setOpen}><DialogContent><DialogHeader><DialogTitle>{listing ? 'Report this listing' : 'Report a handoff problem'}</DialogTitle><DialogDescription>{listing ? 'Private details go to the campus moderators.' : 'The exchange enters review and keeps its holds until outcomes are resolved.'}</DialogDescription></DialogHeader><label htmlFor="report-kind">What happened?</label><Pick id="report-kind" label="Problem type" value={kind} onChange={setKind} options={[{ value: 'condition', label: 'Item condition differs' }, { value: 'missing_item', label: 'An item is missing' }, { value: 'no_show', label: 'Someone did not attend' }, { value: 'inappropriate', label: 'Inappropriate listing or conduct' }, { value: 'other', label: 'Something else' }]} /><label htmlFor="report-details">Details for the moderator</label><textarea id="report-details" value={details} onChange={e => setDetails(e.target.value)} minLength={5} maxLength={1000} rows={4} placeholder="Describe what you observed. Avoid unnecessary personal information." />{error && <p role="alert" className="form-error">{error}</p>}<DialogFooter><button className="secondary" onClick={() => setOpen(false)}>Go back</button><button className="primary" disabled={busy || details.trim().length < 5} onClick={() => action(listing ? 'report.listing' : 'loop.problem', { id, kind, details }).then(() => { setDetails(''); setOpen(false); }).catch(e => setError(e.message))}>Submit report</button></DialogFooter></DialogContent></Dialog>;
}
function ModerationReportActions({ report }: { report: Problem }) {
  const { data, action, busy } = useApp();
  const [open, setOpen] = useState<'listing' | 'membership' | null>(null), [memberId, setMemberId] = useState('choose'), [reason, setReason] = useState(''), [error, setError] = useState('');
  const loop = data.loops.find(l => l.id === report.loopId);
  const listing = data.listings.find(l => l.id === report.listingId);
  const relevant = data.members.filter(m => m.id !== data.actor?.id && (loop ? loop.participants.some(p => p.userId === m.id) : listing ? m.id === listing.ownerId : true));
  function begin(kind: 'listing' | 'membership') { setOpen(kind); setReason(''); setError(''); setMemberId(listing?.ownerId ?? 'choose'); }
  async function save() {
    try {
      await action(open === 'listing' ? 'moderation.listing' : 'moderation.suspend', { id: open === 'listing' ? report.listingId : memberId, reason });
      setOpen(null);
    } catch (e) { setError((e as Error).message); }
  }
  return <>{report.listingId && <button className="secondary" disabled={busy} onClick={() => begin('listing')}>Review listing removal</button>}<button className="secondary" disabled={busy} onClick={() => begin('membership')}>Review membership</button><Dialog open={!!open} onOpenChange={value => !value && setOpen(null)}><DialogContent><DialogHeader><DialogTitle>{open === 'listing' ? 'Remove this reported listing?' : 'Review a member’s access'}</DialogTitle><DialogDescription>Record the evidence and reason. Affected pending proposals end; confirmed exchanges enter review with their holds retained.</DialogDescription></DialogHeader>{open === 'membership' && <><label htmlFor={`reported-member-${report.id}`}>Member to suspend</label><Pick id={`reported-member-${report.id}`} label="Member to suspend" value={memberId} onChange={setMemberId} options={[{ value: 'choose', label: 'Choose a member after reviewing the evidence' }, ...relevant.map(m => ({ value: m.id, label: m.name }))]} /></>}<label htmlFor={`moderation-reason-${report.id}`}>Evidence and reason</label><textarea id={`moderation-reason-${report.id}`} value={reason} onChange={e => setReason(e.target.value)} rows={4} minLength={5} maxLength={500} />{error && <p role="alert" className="form-error">{error}</p>}<DialogFooter><button className="secondary" onClick={() => setOpen(null)}>Keep as is</button><button className="primary" disabled={busy || reason.trim().length < 5 || (open === 'membership' && memberId === 'choose')} onClick={save}>{open === 'listing' ? 'Remove listing with reason' : 'Suspend selected member'}</button></DialogFooter></DialogContent></Dialog></>;
}
function Moderation() {
  const { data, action, busy } = useApp(); const [selected, setSelected] = useState<Loop | null>(null), [reason, setReason] = useState(''), [outcomes, setOutcomes] = useState<Record<string, string>>({});
  if (data.actor?.role !== 'moderator') return <EmptyState title="Moderator access required" description="This private queue is available only to authorized campus moderators." />;
  const reviews = data.loops.filter(l => l.state === 'NEEDS_REVIEW'), reports = data.problems.filter(p => p.status === 'open');
  return <><PageHeading eyebrow="CAMPUS MODERATION" title="Care for the exchange circle." description="Record evidence and item outcomes. Participant receipts remain their own." /><Tabs defaultValue="reviews"><TabsList className="section-tabs"><TabsTrigger value="reviews">Exchange reviews ({reviews.length})</TabsTrigger><TabsTrigger value="reports">Private reports ({reports.length})</TabsTrigger><TabsTrigger value="loans">Loan reviews ({data.loans.filter(l => l.state === 'NEEDS_REVIEW').length})</TabsTrigger><TabsTrigger value="feedback">Feedback disputes</TabsTrigger><TabsTrigger value="venues">Venue hours</TabsTrigger><TabsTrigger value="maintenance">Service readiness</TabsTrigger></TabsList><TabsContent value="reviews">{reviews.length ? reviews.map(l => <div key={l.id} className="white-panel moderation-row"><div><Status state={l.state} /><h3>{l.participants.length}-person exchange</h3><p>{l.terminalReason}</p><Link href={`/loops/${l.id}`}>Read transfer history</Link></div><button className="primary" onClick={() => { setSelected(l); setReason(''); setOutcomes(Object.fromEntries(l.transfers.map(t => [t.listingId, t.outcome ?? 'unresolved']))); }}>Record outcomes</button></div>) : <EmptyState title="No exchanges need review" description="Uncertain handoffs appear here with all holds retained." />}</TabsContent><TabsContent value="reports">{reports.length ? reports.map(p => <div key={p.id} className="white-panel"><h3>{p.kind.replace('_', ' ')}</h3><p>{p.details}</p><small>{dateTime(p.createdAt)}</small><div className="inline-row">{p.loopId && <Link className="secondary" href={`/loops/${p.loopId}`}>Inspect exchange</Link>}<ModerationReportActions report={p} /></div></div>) : <EmptyState title="No open reports" description="Listing reports and private handoff explanations appear here." />}</TabsContent><TabsContent value="loans"><LoanModeration /></TabsContent><TabsContent value="feedback"><FeedbackModeration /></TabsContent><TabsContent value="venues"><VenueCalendar /></TabsContent><TabsContent value="maintenance"><Maintenance /></TabsContent></Tabs><Dialog open={!!selected} onOpenChange={open => !open && setSelected(null)}><DialogContent className="proposal-dialog"><DialogHeader><DialogTitle>Record every item&apos;s outcome</DialogTitle><DialogDescription>Leave unknown outcomes unresolved. Returned items become paused. You cannot create a participant receipt.</DialogDescription></DialogHeader>{selected?.transfers.map(t => <div key={t.id} className="outcome-row"><label>{t.item.title}</label><Pick value={outcomes[t.listingId] ?? 'unresolved'} onChange={v => setOutcomes(o => ({ ...o, [t.listingId]: v }))} label={`Outcome for ${t.item.title}`} options={[{ value: 'unresolved', label: 'Outcome still unresolved' }, { value: 'recipient', label: 'Verified with recipient' }, { value: 'original_owner', label: 'Returned to original owner' }]} /></div>)}<label htmlFor="resolution-evidence">Evidence and reason</label><textarea id="resolution-evidence" rows={4} value={reason} onChange={e => setReason(e.target.value)} maxLength={1000} /><button className="primary" disabled={busy || reason.trim().length < 10} onClick={() => selected && action('moderation.resolve', { id: selected.id, expectedVersion: selected.version, expectedSequence: selected.sequence, reason, outcomes: selected.transfers.map(t => ({ listingId: t.listingId, outcome: outcomes[t.listingId] })) }).then(() => setSelected(null)).catch(() => {})}>Save verified outcomes</button></DialogContent></Dialog></>;
}
function Help() { return <><PageHeading eyebrow="A LITTLE HELP GOES A LONG WAY" title="Make a good exchange." description="A clear plan, everyone's agreement, and an honest handoff." /><div className="help-grid"><LoanHelp /><div className="white-panel"><h2>How a loop works</h2><p>A direct swap connects two people who want each other&apos;s item. A three-person loop finds an extra connection: Alice gives a lock to Carol, Carol gives a textbook to Bob, and Bob gives a calculator to Alice.</p><MiniCycle /><p>Each person gives one whole item and receives one. Matching follows your structured wants, minimum condition, shared venues, and one common 30-minute slot.</p></div><div className="white-panel"><h2>Agreement comes first</h2><p>A proposal fixes the items, transfer direction, location, and exact meetup time. Creating a proposal records your own acceptance. Everyone else decides independently.</p><p>Pending proposals hold nothing. Only a complete, valid set of approvals reserves all items and members together. Another exchange may confirm first.</p><h2>Meet publicly</h2><p>Meet at the approved campus venue. Check condition before you accept an item. No cash, shipping, home addresses, deposits, or bundles are part of this app.</p><h2>Report what happened</h2><p>Only the intended recipient can report a receipt. An exchange completes after all receipts and no open problem. Software can reserve items digitally; it cannot guarantee a simultaneous physical handoff.</p></div><div className="white-panel"><h2>When plans change</h2><p>Editing an item, wants, or meeting preferences makes affected pending proposals stale. Confirmed plans stay frozen.</p><p>Before the meetup, with no receipt or problem, cancellation releases all holds. Later cancellation, partial handoff, a problem, or overdue receipts enters review. Uncertain items stay held.</p><p>Moderators record per-item outcomes. Items returned to their owners are paused until the owner republishes them.</p></div><div className="white-panel"><h2>Your privacy</h2><p>Other members see your display name, public item details, and shared meetup options. They cannot read your full availability, private reports, blocks, or notifications.</p><p>Photos are optional. Upload JPG, PNG, or WebP photos of your own item. Images are resized, validated, and stripped of location metadata. Unpublished photos are private to their uploader and authorized moderators. Agreement participants retain access to the photos in their agreed item snapshot.</p><h2>About this demo</h2><p>This is an isolated synthetic community with fictional members. Separate browser sessions represent separate members. It is prepared for product testing, with pilot provisioning, background scheduling, archival, backups, and moderation operations documented as remaining release work.</p></div></div></>; }
